    if constexpr (std::is_floating_point_v<T>)
      if (!std::isfinite(x)) throw std::invalid_argument("LineContainer: nonfinite x");
#else
    (void)x;
#endif
  }
#if defined(__GNUC__) || defined(__clang__)
  __attribute__((always_inline))
#endif
